-- Portal SimonSports — backend Supabase definitivo
-- Apps Script deixa o caminho operacional. Firebase permanece como identidade.
-- Nenhuma senha do legado é migrada.

create extension if not exists pgcrypto;

alter table public.usuarios add column if not exists nome_publico text;
alter table public.usuarios add column if not exists receber_aviso_novo_bolao boolean not null default true;
alter table public.pagamentos add column if not exists aquisicao_id uuid;
alter table public.pagamentos add column if not exists id_transacao text;
alter table public.pagamentos add column if not exists autenticacao text;
alter table public.pagamentos add column if not exists validacao text;
alter table public.pagamentos add column if not exists mes_referencia text;
alter table public.pagamentos add column if not exists tipo_cota text;
alter table public.pagamentos add column if not exists fracao_cota numeric(12,6);
alter table public.pagamentos add column if not exists qtd_cotas numeric(12,4);
alter table public.pagamentos add column if not exists cotas_equivalentes numeric(12,6);
alter table public.pagamentos add column if not exists valor_esperado numeric(14,2);
alter table public.pagamentos add column if not exists valor_transferido numeric(14,2);
alter table public.pagamentos add column if not exists nome_arquivo text;
alter table public.pagamentos add column if not exists mime_type text;
alter table public.pagamentos add column if not exists arquivo_url text;
alter table public.pagamentos add column if not exists processamento_status text;
alter table public.pagamentos add column if not exists data_transferencia timestamptz;
alter table public.pagamentos add column if not exists data_comprovante timestamptz;
alter table public.pagamentos add column if not exists tipo_comprovante text;
alter table public.pagamentos add column if not exists banco_destino text;
alter table public.pagamentos add column if not exists agencia_destino text;
alter table public.pagamentos add column if not exists operacao_destino text;
alter table public.pagamentos add column if not exists conta_destino text;
alter table public.palpites add column if not exists jogo integer not null default 1;

create table if not exists public.base_loterias (
 nome text primary key,qtd_min integer not null,qtd_max integer not null,faixa_numeros integer not null,
 qtd_palpite integer not null default 10,imagem_id text,qtd_sorteada integer not null,faixas_premiacao text,
 exibir_probabilidade boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.dados_recebimento (
 id uuid primary key default gen_random_uuid(),loteria text not null,tipo_recebimento text not null default 'PIX',
 nome_completo text not null,tipo_pix text,chave_pix text,banco text,agencia text,conta text,operacao text,obs text,
 ativo boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create unique index if not exists dados_recebimento_loteria_tipo_uq on public.dados_recebimento(lower(loteria),lower(tipo_recebimento));
create table if not exists public.regulamentos (
 versao text primary key,titulo text,texto text not null,ativo boolean not null default false,
 publicado_em timestamptz not null default now(),updated_at timestamptz not null default now()
);
create unique index if not exists regulamento_ativo_uq on public.regulamentos(ativo) where ativo;
create table if not exists public.permissoes_paginas (
 pagina text primary key,admin boolean not null default false,usuario boolean not null default false,privado boolean not null default false,updated_at timestamptz not null default now()
);
create table if not exists public.solicitacoes_cadastro (
 id uuid primary key default gen_random_uuid(),firebase_uid text,data_solicitacao timestamptz not null default now(),nome text not null,
 nome_publico text,email text not null,telegram text,celular text,status text not null default 'PENDENTE',cotas text,tipo text,
 comprovante text,bolao text,aceite_regulamento boolean not null default false,data_aceite_regulamento timestamptz,
 versao_regulamento text,cpf text,receber_aviso_novo_bolao boolean not null default true,origem text,obs_admin text,
 processado_usuarios boolean not null default false,id_usuario_gerado text,data_processamento timestamptz,erro_aprovacao text,
 data_erro_aprovacao timestamptz,aba_id text,email_acesso_enviado_em timestamptz,erro_envio_email text,legacy_row integer,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create unique index if not exists solicitacoes_email_uq on public.solicitacoes_cadastro(lower(email));
create index if not exists solicitacoes_status_idx on public.solicitacoes_cadastro(status);
create table if not exists public.aquisicoes_cotas (
 id uuid primary key default gen_random_uuid(),usuario_id uuid not null references public.usuarios(id) on delete cascade,
 bolao_id text not null references public.boloes(id) on delete cascade,participacao_id uuid not null references public.participacoes(id) on delete cascade,
 qtd_cotas numeric(12,4) not null,tipo_cota text not null default 'INTEGRAL',fracao_cota numeric(12,6) not null default 1,
 cotas_equivalentes numeric(12,6) not null,valor_total numeric(14,2) not null,valor_pagamento_agora numeric(14,2) not null,
 parcelado boolean not null default false,qtd_parcelas integer not null default 1,qtd_parcelas_bolao integer not null default 1,
 dia_preferencial integer,obs text,status text not null default 'RESERVADO',validade_reserva timestamptz,disponiveis_antes numeric(12,6),
 disponiveis_depois numeric(12,6),data_confirmacao timestamptz,pagamento_id uuid,legacy_id text,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create index if not exists aquisicoes_usuario_idx on public.aquisicoes_cotas(usuario_id);
create index if not exists aquisicoes_bolao_idx on public.aquisicoes_cotas(bolao_id);
create index if not exists aquisicoes_status_idx on public.aquisicoes_cotas(status);
do $$ begin if not exists(select 1 from pg_constraint where conname='pagamentos_aquisicao_fk') then
 alter table public.pagamentos add constraint pagamentos_aquisicao_fk foreign key(aquisicao_id) references public.aquisicoes_cotas(id) on delete set null; end if; end $$;
do $$ begin if not exists(select 1 from pg_constraint where conname='aquisicoes_pagamento_fk') then
 alter table public.aquisicoes_cotas add constraint aquisicoes_pagamento_fk foreign key(pagamento_id) references public.pagamentos(id) on delete set null; end if; end $$;
create table if not exists public.jogos_realizados (
 id uuid primary key default gen_random_uuid(),bolao_id text references public.boloes(id) on delete set null,loteria text not null,concurso text,
 data_jogo date,mes_referencia text,obs text,nome_arquivo text,mime_type text,storage_bucket text,storage_path text,tamanho_bytes bigint,
 hash_arquivo text,legacy_drive_url text,image_url text,status text not null default 'ATIVO',enviado_por uuid references public.usuarios(id) on delete set null,
 legacy_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create unique index if not exists jogos_hash_uq on public.jogos_realizados(hash_arquivo) where hash_arquivo is not null and hash_arquivo<>'';
create unique index if not exists jogos_legacy_id_uq on public.jogos_realizados(legacy_id) where legacy_id is not null and legacy_id<>'';
create table if not exists public.notificacoes_log (
 id bigint generated always as identity primary key,canal text not null,bolao_id text,loteria text,destinatario text,tipo text,status text,
 mensagem text,retorno text,message_id text,versao text,ocorrido_em timestamptz,legacy_row integer,created_at timestamptz not null default now()
);
create unique index if not exists notificacoes_legacy_uq on public.notificacoes_log(canal,legacy_row) where legacy_row is not null;
create table if not exists public.legacy_migracao_snapshot (
 origem text not null,legacy_row integer not null,dados jsonb not null,imported_at timestamptz not null default now(),primary key(origem,legacy_row)
);

do $$ begin
 if not exists(select 1 from pg_trigger where tgname='base_loterias_set_updated_at') then create trigger base_loterias_set_updated_at before update on public.base_loterias for each row execute function public.set_updated_at(); end if;
 if not exists(select 1 from pg_trigger where tgname='dados_recebimento_set_updated_at') then create trigger dados_recebimento_set_updated_at before update on public.dados_recebimento for each row execute function public.set_updated_at(); end if;
 if not exists(select 1 from pg_trigger where tgname='regulamentos_set_updated_at') then create trigger regulamentos_set_updated_at before update on public.regulamentos for each row execute function public.set_updated_at(); end if;
 if not exists(select 1 from pg_trigger where tgname='solicitacoes_set_updated_at') then create trigger solicitacoes_set_updated_at before update on public.solicitacoes_cadastro for each row execute function public.set_updated_at(); end if;
 if not exists(select 1 from pg_trigger where tgname='aquisicoes_set_updated_at') then create trigger aquisicoes_set_updated_at before update on public.aquisicoes_cotas for each row execute function public.set_updated_at(); end if;
 if not exists(select 1 from pg_trigger where tgname='jogos_realizados_set_updated_at') then create trigger jogos_realizados_set_updated_at before update on public.jogos_realizados for each row execute function public.set_updated_at(); end if;
end $$;
alter table public.base_loterias enable row level security;alter table public.dados_recebimento enable row level security;alter table public.regulamentos enable row level security;
alter table public.permissoes_paginas enable row level security;alter table public.solicitacoes_cadastro enable row level security;alter table public.aquisicoes_cotas enable row level security;
alter table public.jogos_realizados enable row level security;alter table public.notificacoes_log enable row level security;alter table public.legacy_migracao_snapshot enable row level security;

create or replace function public.pss_claims() returns jsonb language sql stable set search_path=public,pg_temp as $$select coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb)$$;
create or replace function public.pss_claim_sub() returns text language sql stable set search_path=public,pg_temp as $$select nullif(public.pss_claims()->>'sub','')$$;
create or replace function public.pss_claim_email() returns text language sql stable set search_path=public,pg_temp as $$select lower(nullif(public.pss_claims()->>'email',''))$$;
create or replace function public.pss_usuario_id_atual() returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare v_sub text:=public.pss_claim_sub();v_email text:=public.pss_claim_email();v_id uuid;begin
 if v_sub is null then return null;end if;select id into v_id from public.usuarios where firebase_uid=v_sub limit 1;if v_id is not null then return v_id;end if;
 if v_email is not null then select id into v_id from public.usuarios where lower(email)=v_email limit 1;if v_id is not null then update public.usuarios set firebase_uid=coalesce(firebase_uid,v_sub) where id=v_id;return v_id;end if;end if;return null;end$$;
create or replace function public.pss_is_admin() returns boolean language plpgsql security definer set search_path=public,pg_temp as $$
declare v_id uuid:=public.pss_usuario_id_atual();v_ok boolean:=false;begin if v_id is null then return false;end if;
 select aprovado and upper(coalesce(status,'')) in('ATIVO','APROVADO') and(upper(coalesce(perfil,'')) like '%ADMIN%' or upper(coalesce(perfil,'')) like '%MESTRE%') into v_ok from public.usuarios where id=v_id;return coalesce(v_ok,false);end$$;
create or replace function public.pss_usuario_aprovado() returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare v_id uuid:=public.pss_usuario_id_atual();v_ok boolean;begin if v_id is null then raise exception 'USUARIO_NAO_LOCALIZADO';end if;
 select aprovado and upper(coalesce(status,'')) in('ATIVO','APROVADO') into v_ok from public.usuarios where id=v_id;if not coalesce(v_ok,false) then raise exception 'CADASTRO_NAO_APROVADO';end if;return v_id;end$$;

create or replace function public.pss_regulamento_atual() returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select coalesce((select jsonb_build_object('versao',versao,'titulo',titulo,'texto',texto) from public.regulamentos where ativo order by publicado_em desc limit 1),'{}'::jsonb)$$;
create or replace function public.pss_base_loterias_publica() returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select coalesce(jsonb_agg(jsonb_build_object('nome',nome,'qtdMin',qtd_min,'qtdMax',qtd_max,'range',faixa_numeros,'qtdPalpite',qtd_palpite,'imagemId',imagem_id,'qtdSorteada',qtd_sorteada,'faixasPremiacao',faixas_premiacao,'exibirProbabilidade',exibir_probabilidade) order by nome),'[]'::jsonb) from public.base_loterias$$;
create or replace function public.pss_solicitar_cadastro(p_dados jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_sub text:=public.pss_claim_sub();v_ec text:=public.pss_claim_email();v_email text:=lower(trim(coalesce(p_dados->>'email','')));v_nome text:=trim(coalesce(p_dados->>'nome',''));v_pub text:=trim(coalesce(p_dados->>'nomePublico',p_dados->>'nome_publico',''));v_ok boolean:=lower(coalesce(p_dados->>'aceiteRegulamento',p_dados->>'aceitouRegulamento','false')) in('true','sim','1');v_uid uuid;v_sid uuid;
begin if v_sub is null or v_ec is null then raise exception 'FIREBASE_TOKEN_OBRIGATORIO';end if;if v_email='' or v_email<>v_ec then raise exception 'EMAIL_DIVERGENTE_DO_FIREBASE';end if;if char_length(v_nome)<3 then raise exception 'NOME_INVALIDO';end if;if char_length(v_pub)>60 then raise exception 'NOME_PUBLICO_MAX_60';end if;if not v_ok then raise exception 'ACEITE_REGULAMENTO_OBRIGATORIO';end if;
 insert into public.usuarios(firebase_uid,nome,nome_publico,email,telefone,cpf,status,perfil,aprovado,receber_aviso_novo_bolao) values(v_sub,v_nome,nullif(v_pub,''),v_email,nullif(trim(p_dados->>'telefone'),''),nullif(trim(p_dados->>'cpf'),''),'PENDENTE','PARTICIPANTE',false,lower(coalesce(p_dados->>'receberAvisoNovoBolao','sim')) in('true','sim','1'))
 on conflict((lower(email))) where email is not null and email<>'' do update set firebase_uid=excluded.firebase_uid,nome=excluded.nome,nome_publico=excluded.nome_publico,telefone=excluded.telefone,cpf=coalesce(excluded.cpf,public.usuarios.cpf),receber_aviso_novo_bolao=excluded.receber_aviso_novo_bolao,updated_at=now() returning id into v_uid;
 insert into public.solicitacoes_cadastro(firebase_uid,nome,nome_publico,email,telegram,celular,status,cotas,tipo,bolao,aceite_regulamento,data_aceite_regulamento,versao_regulamento,cpf,receber_aviso_novo_bolao,origem)
 values(v_sub,v_nome,nullif(v_pub,''),v_email,nullif(trim(p_dados->>'telefone'),''),nullif(trim(p_dados->>'telefone'),''),'PENDENTE',coalesce(p_dados->>'cotas','0'),coalesce(p_dados->>'tipo','Novo Cadastro / Acesso'),nullif(trim(p_dados->>'loteria'),''),true,now(),coalesce(p_dados->>'versaoRegulamento','2026.2'),nullif(trim(p_dados->>'cpf'),''),lower(coalesce(p_dados->>'receberAvisoNovoBolao','sim')) in('true','sim','1'),coalesce(p_dados->>'origem','SUPABASE_DIRETO'))
 on conflict((lower(email))) do update set firebase_uid=excluded.firebase_uid,nome=excluded.nome,nome_publico=excluded.nome_publico,telegram=excluded.telegram,celular=excluded.celular,status='PENDENTE',aceite_regulamento=true,data_aceite_regulamento=now(),versao_regulamento=excluded.versao_regulamento,cpf=coalesce(excluded.cpf,public.solicitacoes_cadastro.cpf),receber_aviso_novo_bolao=excluded.receber_aviso_novo_bolao,origem=excluded.origem,updated_at=now() returning id into v_sid;
 insert into public.auditoria(usuario_id,entidade,entidade_id,acao,dados_depois,origem) values(v_uid,'SOLICITACAO_CADASTRO',v_sid::text,'SOLICITAR',jsonb_build_object('email',v_email,'versao',coalesce(p_dados->>'versaoRegulamento','2026.2')),'SUPABASE');
 return jsonb_build_object('ok',true,'sucesso',true,'status','PENDENTE','msg','Solicitação de acesso enviada com sucesso. Aguarde aprovação da administração.');end$$;
create or replace function public.pss_me() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_id uuid:=public.pss_usuario_id_atual();r record;begin if v_id is null then return jsonb_build_object('ok',false,'localizado',false);end if;select * into r from public.usuarios where id=v_id;return jsonb_build_object('ok',true,'localizado',true,'id',r.id,'firebaseUid',r.firebase_uid,'nome',r.nome,'nomePublico',r.nome_publico,'email',r.email,'telefone',r.telefone,'status',r.status,'perfil',r.perfil,'role',r.perfil,'aprovado',r.aprovado,'receberAvisoNovoBolao',r.receber_aviso_novo_bolao);end$$;
create or replace function public.pss_boloes_usuario() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_uid uuid:=public.pss_usuario_aprovado();begin return coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'nome',b.nome,'loteria',b.loteria,'status',b.status,'statusOriginal',b.status_original,'dataSorteio',b.data_sorteio,'inicioPagamento',b.inicio_pagamento,'fimPagamento',b.fim_pagamento,'inicioPalpite',b.inicio_palpite,'fimPalpite',b.fim_palpite,'valorCota',b.valor_cota,'totalCotas',b.total_cotas,'cotasAdquiridas',b.cotas_adquiridas,'cotasDisponiveis',coalesce(b.cotas_disponiveis,b.total_cotas-b.cotas_adquiridas),'qtdParcelas',b.qtd_parcelas,'premiacao',b.premiacao,'premioPorCota',b.premio_por_cota,'range',b.faixa_numeros,'qtdMin',b.qtd_min,'qtdMax',b.qtd_max,'qtdPalpite',b.qtd_palpite,'historico',b.historico,'numerosSorteados',b.numeros_sorteados,'cotasUsuario',coalesce(p.cotas_confirmadas,0),'cotasPendentes',coalesce(p.cotas_pendentes,0),'cotasReservadas',coalesce(p.cotas_reservadas,0),'inscrito',coalesce(p.inscrito,false),'statusParticipacao',p.status) order by b.data_sorteio nulls last,b.nome) from public.boloes b left join public.participacoes p on p.bolao_id=b.id and p.usuario_id=v_uid where upper(coalesce(b.status,''))<>'EXCLUIDO'),'[]'::jsonb);end$$;
create or replace function public.pss_dashboard() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_uid uuid:=public.pss_usuario_aprovado();v_email text;begin select email into v_email from public.usuarios where id=v_uid;return jsonb_build_object('email',v_email,'cotasConfirmadas',coalesce((select sum(cotas_confirmadas) from public.participacoes where usuario_id=v_uid),0),'cotasReservadas',coalesce((select sum(cotas_reservadas) from public.participacoes where usuario_id=v_uid),0),'pagamentos',coalesce((select count(*) from public.pagamentos where usuario_id=v_uid),0),'valorPago',coalesce((select sum(valor) from public.pagamentos where usuario_id=v_uid and upper(status) in('PAGO','CONFIRMADO')),0),'palpites',coalesce((select count(*) from public.palpites where usuario_id=v_uid and upper(status)='ATIVO'),0),'telegramCanalLink',coalesce((select valor#>>'{}' from public.configuracoes where chave='TELEGRAM_CANAL_LINK'),''));end$$;
create or replace function public.pss_dados_recebimento(p_loteria text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin perform public.pss_usuario_aprovado();return coalesce((select jsonb_agg(jsonb_build_object('loteria',loteria,'tipoRecebimento',tipo_recebimento,'nomeCompleto',nome_completo,'tipoPix',tipo_pix,'chavePix',chave_pix,'banco',banco,'agencia',agencia,'conta',conta,'operacao',operacao,'obs',obs,'ativo',ativo) order by loteria) from public.dados_recebimento where ativo and(p_loteria is null or p_loteria='' or lower(loteria)=lower(p_loteria) or lower(p_loteria) like lower(loteria)||'%' or lower(loteria) like lower(p_loteria)||'%')),'[]'::jsonb);end$$;
create or replace function public.pss_palpite_info(p_bolao text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_uid uuid:=public.pss_usuario_aprovado();b public.boloes%rowtype;v_qtd int;v_range int;begin select * into b from public.boloes where id=p_bolao or lower(nome)=lower(p_bolao) or lower(loteria)=lower(p_bolao) limit 1;if b.id is null then raise exception 'BOLAO_NAO_LOCALIZADO';end if;select coalesce(b.qtd_palpite,bl.qtd_palpite,6),coalesce(b.faixa_numeros,bl.faixa_numeros,60) into v_qtd,v_range from public.base_loterias bl where lower(bl.nome)=lower(coalesce(b.loteria,b.nome)) or lower(b.nome) like lower(bl.nome)||'%' limit 1;return jsonb_build_object('id',b.id,'loteria',b.nome,'qtdEscolha',coalesce(v_qtd,b.qtd_palpite,6),'qtdPalpite',coalesce(v_qtd,b.qtd_palpite,6),'nMax',coalesce(v_range,b.faixa_numeros,60),'range',coalesce(v_range,b.faixa_numeros,60),'inicioPalpite',b.inicio_palpite,'fimPalpite',b.fim_palpite);end$$;
create or replace function public.pss_palpite_status(p_bolao text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_uid uuid:=public.pss_usuario_aprovado();b public.boloes%rowtype;p public.participacoes%rowtype;begin select * into b from public.boloes where id=p_bolao or lower(nome)=lower(p_bolao) or lower(loteria)=lower(p_bolao) limit 1;if b.id is null then raise exception 'BOLAO_NAO_LOCALIZADO';end if;select * into p from public.participacoes where bolao_id=b.id and usuario_id=v_uid;return jsonb_build_object('cotas',coalesce(p.cotas_confirmadas,0),'maxJogos',greatest(floor(coalesce(p.cotas_confirmadas,0))::int,0),'palpites',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'data',x.enviado_em,'numeros',x.numeros,'status',x.status,'jogo',x.jogo) order by x.jogo) from public.palpites x where x.bolao_id=b.id and x.usuario_id=v_uid and upper(x.status)<>'EXCLUIDO'),'[]'::jsonb));end$$;
create or replace function public.pss_salvar_palpite(p_bolao text,p_numeros jsonb,p_jogo integer default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_uid uuid:=public.pss_usuario_aprovado();b public.boloes%rowtype;p public.participacoes%rowtype;v_qtd int;v_range int;v_max int;v_jogo int;v_count int;v_dist int;v_bad int;v_id uuid;begin
 select * into b from public.boloes where id=p_bolao or lower(nome)=lower(p_bolao) or lower(loteria)=lower(p_bolao) limit 1;if b.id is null then raise exception 'BOLAO_NAO_LOCALIZADO';end if;if current_date<coalesce(b.inicio_palpite,current_date) or current_date>coalesce(b.fim_palpite,current_date) then raise exception 'PRAZO_PALPITE_FECHADO';end if;select * into p from public.participacoes where bolao_id=b.id and usuario_id=v_uid;if p.id is null or not p.inscrito or coalesce(p.cotas_confirmadas,0)<=0 then raise exception 'PARTICIPACAO_NAO_CONFIRMADA';end if;
 select coalesce(b.qtd_palpite,bl.qtd_palpite,6),coalesce(b.faixa_numeros,bl.faixa_numeros,60) into v_qtd,v_range from public.base_loterias bl where lower(bl.nome)=lower(coalesce(b.loteria,b.nome)) or lower(b.nome) like lower(bl.nome)||'%' limit 1;v_qtd:=coalesce(v_qtd,b.qtd_palpite,6);v_range:=coalesce(v_range,b.faixa_numeros,60);v_count:=jsonb_array_length(coalesce(p_numeros,'[]'::jsonb));if v_count<>v_qtd then raise exception 'QUANTIDADE_NUMEROS_INVALIDA:%',v_qtd;end if;select count(distinct value::int),count(*) filter(where value::int<1 or value::int>v_range) into v_dist,v_bad from jsonb_array_elements_text(p_numeros);if v_dist<>v_count then raise exception 'NUMEROS_REPETIDOS';end if;if v_bad>0 then raise exception 'NUMERO_FORA_DO_INTERVALO_1_%',v_range;end if;v_max:=greatest(floor(p.cotas_confirmadas)::int,0);if v_max<1 then raise exception 'SEM_COTAS_CONFIRMADAS';end if;v_jogo:=coalesce(p_jogo,(select coalesce(max(jogo),0)+1 from public.palpites where bolao_id=b.id and usuario_id=v_uid));if v_jogo<1 or v_jogo>v_max then raise exception 'LIMITE_PALPITES:%',v_max;end if;select id into v_id from public.palpites where bolao_id=b.id and usuario_id=v_uid and jogo=v_jogo limit 1;if v_id is null then insert into public.palpites(bolao_id,usuario_id,numeros,texto_original,status,jogo,enviado_em) values(b.id,v_uid,p_numeros,(select string_agg(lpad(value,2,'0'),'-' order by value::int) from jsonb_array_elements_text(p_numeros)),'ATIVO',v_jogo,now()) returning id into v_id;else update public.palpites set numeros=p_numeros,texto_original=(select string_agg(lpad(value,2,'0'),'-' order by value::int) from jsonb_array_elements_text(p_numeros)),status='ATIVO',enviado_em=now(),updated_at=now() where id=v_id;end if;insert into public.auditoria(usuario_id,entidade,entidade_id,acao,dados_depois,origem) values(v_uid,'PALPITE',v_id::text,'SALVAR',jsonb_build_object('bolao',b.id,'jogo',v_jogo,'numeros',p_numeros),'SUPABASE');return jsonb_build_object('ok',true,'sucesso',true,'id',v_id,'jogo',v_jogo,'maxJogos',v_max);end$$;
create or replace function public.pss_reservar_cotas(p_bolao text,p_qtd numeric,p_fracao text default '1',p_dia_preferencial integer default null,p_obs text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_uid uuid:=public.pss_usuario_aprovado();b public.boloes%rowtype;v_part uuid;v_frac numeric;v_eq numeric;v_antes numeric;v_depois numeric;v_valor numeric;v_aq uuid;v_tipo text;v_parc int;begin if p_qtd is null or p_qtd<=0 then raise exception 'QUANTIDADE_COTAS_INVALIDA';end if;v_frac:=case trim(coalesce(p_fracao,'1')) when '1' then 1 when '1/2' then .5 when '1/3' then 1.0/3 when '1/4' then .25 when '1/5' then .2 else null end;if v_frac is null then raise exception 'FRACAO_NAO_PERMITIDA';end if;select * into b from public.boloes where id=p_bolao or lower(nome)=lower(p_bolao) or lower(loteria)=lower(p_bolao) for update limit 1;if b.id is null then raise exception 'BOLAO_NAO_LOCALIZADO';end if;if upper(coalesce(b.status,'')) not in('ATIVO','ABERTO') then raise exception 'BOLAO_NAO_ATIVO';end if;if current_date<coalesce(b.inicio_pagamento,current_date) or current_date>coalesce(b.fim_pagamento,current_date) then raise exception 'PRAZO_PAGAMENTO_FECHADO';end if;v_eq:=round(p_qtd*v_frac,6);v_antes:=coalesce(b.cotas_disponiveis,b.total_cotas-b.cotas_adquiridas,0);if v_eq>v_antes then raise exception 'COTAS_INSUFICIENTES:DISPONIVEIS_%',v_antes;end if;v_depois:=v_antes-v_eq;v_valor:=round(coalesce(b.valor_cota,0)*v_eq,2);v_parc:=greatest(coalesce(b.qtd_parcelas,1),1);v_tipo:=case when v_frac=1 then 'INTEGRAL' else 'FRACIONADA' end;insert into public.participacoes(bolao_id,usuario_id,status,inscrito,cotas_reservadas) values(b.id,v_uid,'RESERVADO',false,v_eq) on conflict(bolao_id,usuario_id) do update set cotas_reservadas=public.participacoes.cotas_reservadas+v_eq,status=case when public.participacoes.inscrito then public.participacoes.status else 'RESERVADO' end,updated_at=now() returning id into v_part;insert into public.aquisicoes_cotas(usuario_id,bolao_id,participacao_id,qtd_cotas,tipo_cota,fracao_cota,cotas_equivalentes,valor_total,valor_pagamento_agora,parcelado,qtd_parcelas,qtd_parcelas_bolao,dia_preferencial,obs,status,validade_reserva,disponiveis_antes,disponiveis_depois) values(v_uid,b.id,v_part,p_qtd,v_tipo,v_frac,v_eq,v_valor,round(v_valor/v_parc,2),v_parc>1,v_parc,v_parc,p_dia_preferencial,p_obs,'RESERVADO',least(coalesce(b.fim_pagamento,current_date+7)::timestamptz,now()+interval '7 days'),v_antes,v_depois) returning id into v_aq;insert into public.cotas(participacao_id,quantidade,fracao,valor_unitario,valor_total,status,origem,legacy_id) values(v_part,v_eq,trim(coalesce(p_fracao,'1')),b.valor_cota,v_valor,'RESERVADO','SUPABASE',v_aq::text);update public.boloes set cotas_disponiveis=v_depois,updated_at=now() where id=b.id;insert into public.auditoria(usuario_id,entidade,entidade_id,acao,dados_depois,origem) values(v_uid,'AQUISICAO_COTA',v_aq::text,'RESERVAR',jsonb_build_object('bolao',b.id,'qtd',p_qtd,'fracao',p_fracao,'equivalente',v_eq,'valor',v_valor),'SUPABASE');return jsonb_build_object('ok',true,'sucesso',true,'idAquisicao',v_aq,'cotasEquivalentes',v_eq,'valorTotal',v_valor,'valorPagamentoAgora',round(v_valor/v_parc,2),'disponiveisDepois',v_depois,'validadeReserva',(select validade_reserva from public.aquisicoes_cotas where id=v_aq));end$$;
create or replace function public.pss_registrar_comprovante(p_dados jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_uid uuid:=public.pss_usuario_aprovado();v_aq public.aquisicoes_cotas%rowtype;v_pag uuid;v_comp uuid;v_hash text:=nullif(trim(p_dados->>'hash'),'');v_path text:=trim(coalesce(p_dados->>'storagePath',''));v_mime text:=lower(coalesce(p_dados->>'mimeType',''));v_size bigint:=coalesce(nullif(p_dados->>'tamanhoBytes','')::bigint,0);v_sub text:=public.pss_claim_sub();v_status text:='PENDENTE';begin if v_path='' or position(v_sub||'/' in v_path)<>1 then raise exception 'CAMINHO_STORAGE_INVALIDO';end if;if v_mime not in('image/jpeg','image/png','application/pdf','image/webp') then raise exception 'FORMATO_COMPROVANTE_NAO_PERMITIDO';end if;if v_size<=0 or v_size>15728640 then raise exception 'TAMANHO_COMPROVANTE_INVALIDO';end if;if v_hash is not null and exists(select 1 from public.comprovantes where hash_arquivo=v_hash) then raise exception 'COMPROVANTE_DUPLICADO';end if;select * into v_aq from public.aquisicoes_cotas where id=nullif(p_dados->>'aquisicaoId','')::uuid and usuario_id=v_uid for update;if v_aq.id is null then raise exception 'AQUISICAO_NAO_LOCALIZADA';end if;if v_aq.status not in('RESERVADO','PENDENTE','COMPROVANTE_ENVIADO') then raise exception 'AQUISICAO_NAO_RECEBE_COMPROVANTE';end if;if now()>coalesce(v_aq.validade_reserva,now()+interval '1 minute') then v_status:='EM_ANALISE';end if;insert into public.pagamentos(usuario_id,bolao_id,participacao_id,aquisicao_id,valor,status,forma_pagamento,hash_comprovante,observacao,nome_arquivo,mime_type,arquivo_url,processamento_status,tipo_cota,fracao_cota,qtd_cotas,cotas_equivalentes,valor_esperado) values(v_uid,v_aq.bolao_id,v_aq.participacao_id,v_aq.id,v_aq.valor_pagamento_agora,v_status,coalesce(p_dados->>'formaPagamento','PIX'),v_hash,nullif(p_dados->>'obs',''),p_dados->>'nomeArquivo',v_mime,v_path,'AGUARDANDO_VALIDACAO',v_aq.tipo_cota,v_aq.fracao_cota,v_aq.qtd_cotas,v_aq.cotas_equivalentes,v_aq.valor_pagamento_agora) returning id into v_pag;insert into public.comprovantes(pagamento_id,usuario_id,nome_arquivo,storage_bucket,storage_path,mime_type,tamanho_bytes,hash_arquivo,status,enviado_por) values(v_pag,v_uid,p_dados->>'nomeArquivo','comprovantes',v_path,v_mime,v_size,v_hash,'RECEBIDO',v_uid) returning id into v_comp;update public.aquisicoes_cotas set status='COMPROVANTE_ENVIADO',pagamento_id=v_pag,updated_at=now() where id=v_aq.id;insert into public.auditoria(usuario_id,entidade,entidade_id,acao,dados_depois,origem) values(v_uid,'COMPROVANTE',v_comp::text,'ENVIAR',jsonb_build_object('pagamento',v_pag,'aquisicao',v_aq.id,'hash',v_hash,'status',v_status),'SUPABASE');return jsonb_build_object('ok',true,'sucesso',true,'pagamentoId',v_pag,'comprovanteId',v_comp,'status',v_status);end$$;
create or replace function public.pss_historico_comprovantes() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_uid uuid:=public.pss_usuario_aprovado();begin return coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'data',c.created_at,'nomeArquivo',c.nome_arquivo,'mimeType',c.mime_type,'status',c.status,'url',coalesce(c.legacy_drive_url,c.storage_path),'pagamentoId',c.pagamento_id,'loteria',b.nome,'valor',p.valor,'statusPagamento',p.status) order by c.created_at desc) from public.comprovantes c left join public.pagamentos p on p.id=c.pagamento_id left join public.boloes b on b.id=p.bolao_id where c.usuario_id=v_uid),'[]'::jsonb);end$$;
create or replace function public.pss_jogos_realizados(p_loteria text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin perform public.pss_usuario_aprovado();return coalesce((select jsonb_agg(jsonb_build_object('id',id,'loteria',loteria,'concurso',concurso,'dataJogo',data_jogo,'mesReferencia',mes_referencia,'obs',obs,'nomeArquivo',nome_arquivo,'mimeType',mime_type,'url',coalesce(legacy_drive_url,storage_path),'imageUrl',image_url,'status',status,'dataEnvio',created_at) order by created_at desc) from public.jogos_realizados where upper(status)<>'EXCLUIDO' and(p_loteria is null or p_loteria='' or lower(loteria)=lower(p_loteria))),'[]'::jsonb);end$$;

create or replace function public.pss_admin_usuarios() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;return coalesce((select jsonb_agg(jsonb_build_object('id',id,'nome',nome,'nomePublico',nome_publico,'email',email,'telefone',telefone,'cpf',cpf,'rg',rg,'status',status,'perfil',perfil,'aprovado',aprovado,'receberAvisoNovoBolao',receber_aviso_novo_bolao,'createdAt',created_at,'updatedAt',updated_at) order by nome) from public.usuarios),'[]'::jsonb);end$$;
create or replace function public.pss_admin_solicitacoes() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;return coalesce((select jsonb_agg(jsonb_build_object('id',id,'data',data_solicitacao,'nome',nome,'nomePublico',nome_publico,'email',email,'telegram',telegram,'celular',celular,'status',status,'cotas',cotas,'tipo',tipo,'bolao',bolao,'aceiteRegulamento',aceite_regulamento,'dataAceiteRegulamento',data_aceite_regulamento,'versaoRegulamento',versao_regulamento,'cpf',cpf,'receberAvisoNovoBolao',receber_aviso_novo_bolao,'origem',origem,'obsAdmin',obs_admin,'processadoUsuarios',processado_usuarios,'idUsuarioGerado',id_usuario_gerado,'dataProcessamento',data_processamento,'erroAprovacao',erro_aprovacao,'abaId',aba_id,'emailAcessoEnviadoEm',email_acesso_enviado_em,'erroEnvioEmail',erro_envio_email) order by data_solicitacao desc) from public.solicitacoes_cadastro),'[]'::jsonb);end$$;
create or replace function public.pss_admin_pagamentos() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;return coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'data',coalesce(p.data_pagamento,p.created_at),'email',u.email,'nome',u.nome,'loteria',b.nome,'status',p.status,'valor',p.valor,'pagador',p.pagador,'recebedor',p.recebedor,'chavePix',p.chave_pix,'idTransacao',p.id_transacao,'autenticacao',p.autenticacao,'validacao',p.validacao,'mesReferencia',p.mes_referencia,'tipoCota',p.tipo_cota,'fracaoCota',p.fracao_cota,'qtdCotas',p.qtd_cotas,'cotasEquivalentes',p.cotas_equivalentes,'valorEsperado',p.valor_esperado,'valorTransferido',p.valor_transferido,'nomeArquivo',p.nome_arquivo,'mimeType',p.mime_type,'arquivoUrl',p.arquivo_url,'processamentoStatus',p.processamento_status,'observacao',p.observacao,'aquisicaoId',p.aquisicao_id) order by coalesce(p.data_pagamento,p.created_at) desc) from public.pagamentos p left join public.usuarios u on u.id=p.usuario_id left join public.boloes b on b.id=p.bolao_id),'[]'::jsonb);end$$;
create or replace function public.pss_admin_participantes() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;return coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'idBolao',p.bolao_id,'loteria',b.nome,'nome',u.nome,'nomePublico',u.nome_publico,'email',u.email,'status',p.status,'inscrito',p.inscrito,'cotas',p.cotas_confirmadas,'cotasConfirmadas',p.cotas_confirmadas,'cotasPendentes',p.cotas_pendentes,'cotasReservadas',p.cotas_reservadas,'updatedAt',p.updated_at) order by b.nome,u.nome) from public.participacoes p join public.usuarios u on u.id=p.usuario_id join public.boloes b on b.id=p.bolao_id),'[]'::jsonb);end$$;
create or replace function public.pss_admin_base_loterias() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;return public.pss_base_loterias_publica();end$$;
create or replace function public.pss_admin_dados_recebimento() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;return coalesce((select jsonb_agg(to_jsonb(d)-'created_at'-'updated_at' order by loteria) from public.dados_recebimento d),'[]'::jsonb);end$$;
create or replace function public.pss_admin_aprovar_solicitacao(p_email text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_admin uuid:=public.pss_usuario_id_atual();s public.solicitacoes_cadastro%rowtype;v_uid uuid;begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;select * into s from public.solicitacoes_cadastro where lower(email)=lower(trim(p_email)) for update;if s.id is null then raise exception 'SOLICITACAO_NAO_LOCALIZADA';end if;insert into public.usuarios(firebase_uid,nome,nome_publico,email,telefone,cpf,status,perfil,aprovado,receber_aviso_novo_bolao) values(s.firebase_uid,s.nome,s.nome_publico,lower(s.email),coalesce(s.celular,s.telegram),s.cpf,'ATIVO','PARTICIPANTE',true,s.receber_aviso_novo_bolao) on conflict((lower(email))) where email is not null and email<>'' do update set firebase_uid=coalesce(excluded.firebase_uid,public.usuarios.firebase_uid),nome=excluded.nome,nome_publico=excluded.nome_publico,telefone=excluded.telefone,cpf=coalesce(excluded.cpf,public.usuarios.cpf),status='ATIVO',aprovado=true,receber_aviso_novo_bolao=excluded.receber_aviso_novo_bolao,updated_at=now() returning id into v_uid;update public.solicitacoes_cadastro set status='APROVADO',processado_usuarios=true,id_usuario_gerado=coalesce(id_usuario_gerado,v_uid::text),data_processamento=now(),erro_aprovacao=null,updated_at=now() where id=s.id;insert into public.auditoria(usuario_id,entidade,entidade_id,acao,dados_depois,origem) values(v_admin,'SOLICITACAO_CADASTRO',s.id::text,'APROVAR',jsonb_build_object('email',s.email,'usuarioId',v_uid),'SUPABASE');return jsonb_build_object('ok',true,'sucesso',true,'email',s.email,'usuarioId',v_uid,'status','APROVADO');end$$;
create or replace function public.pss_admin_recusar_solicitacao(p_email text,p_motivo text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_admin uuid:=public.pss_usuario_id_atual();v_id uuid;begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;update public.solicitacoes_cadastro set status='RECUSADO',obs_admin=coalesce(nullif(trim(p_motivo),''),obs_admin),updated_at=now() where lower(email)=lower(trim(p_email)) returning id into v_id;if v_id is null then raise exception 'SOLICITACAO_NAO_LOCALIZADA';end if;update public.usuarios set status='RECUSADO',aprovado=false,updated_at=now() where lower(email)=lower(trim(p_email));insert into public.auditoria(usuario_id,entidade,entidade_id,acao,dados_depois,origem) values(v_admin,'SOLICITACAO_CADASTRO',v_id::text,'RECUSAR',jsonb_build_object('email',p_email,'motivo',p_motivo),'SUPABASE');return jsonb_build_object('ok',true,'sucesso',true,'status','RECUSADO');end$$;
create or replace function public.pss_admin_usuario_perfil(p_email text,p_perfil text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_admin uuid:=public.pss_usuario_id_atual();v_id uuid;v_perfil text:=upper(trim(p_perfil));begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;if v_perfil not in('PARTICIPANTE','USUARIO','ADMIN','MESTRE') then raise exception 'PERFIL_INVALIDO';end if;update public.usuarios set perfil=v_perfil,updated_at=now() where lower(email)=lower(trim(p_email)) returning id into v_id;if v_id is null then raise exception 'USUARIO_NAO_LOCALIZADO';end if;insert into public.auditoria(usuario_id,entidade,entidade_id,acao,dados_depois,origem) values(v_admin,'USUARIO',v_id::text,'ALTERAR_PERFIL',jsonb_build_object('perfil',v_perfil),'SUPABASE');return jsonb_build_object('ok',true,'sucesso',true,'perfil',v_perfil);end$$;
create or replace function public.pss_admin_pagamento_status(p_id uuid,p_status text,p_obs text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_admin uuid:=public.pss_usuario_id_atual();p public.pagamentos%rowtype;a public.aquisicoes_cotas%rowtype;v_old text;begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;select * into p from public.pagamentos where id=p_id for update;if p.id is null then raise exception 'PAGAMENTO_NAO_LOCALIZADO';end if;v_old:=p.status;update public.pagamentos set status=upper(trim(p_status)),observacao=coalesce(nullif(trim(p_obs),''),observacao),processamento_status=case when upper(trim(p_status)) in('PAGO','CONFIRMADO') then 'VALIDADO' else processamento_status end,updated_at=now() where id=p.id returning * into p;if p.aquisicao_id is not null and upper(trim(p_status)) in('PAGO','CONFIRMADO') and upper(coalesce(v_old,'')) not in('PAGO','CONFIRMADO') then select * into a from public.aquisicoes_cotas where id=p.aquisicao_id for update;if a.id is not null then update public.aquisicoes_cotas set status='CONFIRMADO',data_confirmacao=now(),updated_at=now() where id=a.id;update public.cotas set status='CONFIRMADO',updated_at=now() where legacy_id=a.id::text;update public.participacoes set cotas_reservadas=greatest(cotas_reservadas-a.cotas_equivalentes,0),cotas_confirmadas=cotas_confirmadas+a.cotas_equivalentes,inscrito=true,status='PAGO/CONFIRMADO',updated_at=now() where id=a.participacao_id;update public.boloes set cotas_adquiridas=coalesce(cotas_adquiridas,0)+a.cotas_equivalentes,atualizado_cotas_em=now(),updated_at=now() where id=a.bolao_id;end if;end if;insert into public.auditoria(usuario_id,entidade,entidade_id,acao,dados_antes,dados_depois,origem) values(v_admin,'PAGAMENTO',p.id::text,'ALTERAR_STATUS',jsonb_build_object('status',v_old),jsonb_build_object('status',p.status,'obs',p_obs),'SUPABASE');return jsonb_build_object('ok',true,'sucesso',true,'id',p.id,'status',p.status);end$$;
create or replace function public.pss_admin_salvar_base_loteria(p_dados jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_nome text:=trim(p_dados->>'nome');begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;if v_nome='' then raise exception 'NOME_LOTERIA_OBRIGATORIO';end if;insert into public.base_loterias(nome,qtd_min,qtd_max,faixa_numeros,qtd_palpite,imagem_id,qtd_sorteada,faixas_premiacao,exibir_probabilidade) values(v_nome,(p_dados->>'qtdMin')::int,(p_dados->>'qtdMax')::int,(p_dados->>'range')::int,coalesce((p_dados->>'qtdPalpite')::int,10),nullif(p_dados->>'imagemId',''),(p_dados->>'qtdSorteada')::int,p_dados->>'faixasPremiacao',lower(coalesce(p_dados->>'exibirProbabilidade','sim')) in('true','sim','1')) on conflict(nome) do update set qtd_min=excluded.qtd_min,qtd_max=excluded.qtd_max,faixa_numeros=excluded.faixa_numeros,qtd_palpite=excluded.qtd_palpite,imagem_id=excluded.imagem_id,qtd_sorteada=excluded.qtd_sorteada,faixas_premiacao=excluded.faixas_premiacao,exibir_probabilidade=excluded.exibir_probabilidade,updated_at=now();return jsonb_build_object('ok',true,'sucesso',true,'nome',v_nome);end$$;
create or replace function public.pss_admin_salvar_bolao(p_dados jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_id text:=coalesce(nullif(trim(p_dados->>'id'),''),'ESP-'||(extract(epoch from clock_timestamp())*1000)::bigint::text);begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;if trim(coalesce(p_dados->>'nome',p_dados->>'loteria',''))='' then raise exception 'NOME_BOLAO_OBRIGATORIO';end if;insert into public.boloes(id,nome,loteria,status,status_original,data_sorteio,inicio_pagamento,fim_pagamento,inicio_palpite,fim_palpite,valor_cota,total_cotas,qtd_parcelas,premiacao,premio_por_cota,faixa_numeros,qtd_min,qtd_max,qtd_palpite,historico,exibir_probabilidade,numeros_sorteados) values(v_id,coalesce(p_dados->>'nome',p_dados->>'loteria'),coalesce(p_dados->>'loteria',p_dados->>'nome'),upper(coalesce(p_dados->>'status','ATIVO')),p_dados->>'statusOriginal',nullif(p_dados->>'dataSorteio','')::date,nullif(p_dados->>'inicioPagamento','')::date,nullif(p_dados->>'fimPagamento','')::date,nullif(p_dados->>'inicioPalpite','')::date,nullif(p_dados->>'fimPalpite','')::date,nullif(p_dados->>'valorCota','')::numeric,nullif(p_dados->>'totalCotas','')::numeric,greatest(coalesce(nullif(p_dados->>'qtdParcelas','')::int,1),1),coalesce(nullif(p_dados->>'premiacao','')::numeric,0),coalesce(nullif(p_dados->>'premioPorCota','')::numeric,0),nullif(p_dados->>'range','')::int,nullif(p_dados->>'qtdMin','')::int,nullif(p_dados->>'qtdMax','')::int,nullif(p_dados->>'qtdPalpite','')::int,lower(coalesce(p_dados->>'historico','false')) in('true','sim','1'),lower(coalesce(p_dados->>'exibirProbabilidade','true')) in('true','sim','1'),p_dados->>'numerosSorteados') on conflict(id) do update set nome=excluded.nome,loteria=excluded.loteria,status=excluded.status,status_original=excluded.status_original,data_sorteio=excluded.data_sorteio,inicio_pagamento=excluded.inicio_pagamento,fim_pagamento=excluded.fim_pagamento,inicio_palpite=excluded.inicio_palpite,fim_palpite=excluded.fim_palpite,valor_cota=excluded.valor_cota,total_cotas=excluded.total_cotas,qtd_parcelas=excluded.qtd_parcelas,premiacao=excluded.premiacao,premio_por_cota=excluded.premio_por_cota,faixa_numeros=excluded.faixa_numeros,qtd_min=excluded.qtd_min,qtd_max=excluded.qtd_max,qtd_palpite=excluded.qtd_palpite,historico=excluded.historico,exibir_probabilidade=excluded.exibir_probabilidade,numeros_sorteados=excluded.numeros_sorteados,updated_at=now();update public.boloes set cotas_disponiveis=coalesce(cotas_disponiveis,total_cotas-cotas_adquiridas) where id=v_id;return jsonb_build_object('ok',true,'sucesso',true,'id',v_id);end$$;
create or replace function public.pss_admin_inativar_bolao(p_id text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;update public.boloes set status='INATIVO',updated_at=now() where id=p_id;if not found then raise exception 'BOLAO_NAO_LOCALIZADO';end if;return jsonb_build_object('ok',true,'sucesso',true,'id',p_id,'status','INATIVO');end$$;
create or replace function public.pss_admin_excluir_bolao(p_id text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;update public.boloes set status='EXCLUIDO',historico=true,updated_at=now() where id=p_id;if not found then raise exception 'BOLAO_NAO_LOCALIZADO';end if;return jsonb_build_object('ok',true,'sucesso',true,'id',p_id,'status','EXCLUIDO');end$$;
create or replace function public.pss_admin_configuracoes() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;return coalesce((select jsonb_agg(jsonb_build_object('chave',chave,'valor',valor,'publico',publico,'descricao',descricao) order by chave) from public.configuracoes),'[]'::jsonb);end$$;
create or replace function public.pss_admin_salvar_configuracao(p_chave text,p_valor jsonb,p_publico boolean default false) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_admin uuid:=public.pss_usuario_id_atual();begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;if trim(coalesce(p_chave,''))='' or upper(trim(p_chave)) in('SENHA_ADMIN','TELEGRAM_BOT_TOKEN') then raise exception 'CHAVE_CONFIG_NAO_PERMITIDA';end if;insert into public.configuracoes(chave,valor,publico,updated_by) values(trim(p_chave),coalesce(p_valor,'null'::jsonb),coalesce(p_publico,false),v_admin) on conflict(chave) do update set valor=excluded.valor,publico=excluded.publico,updated_by=v_admin,updated_at=now();return jsonb_build_object('ok',true,'sucesso',true,'chave',trim(p_chave));end$$;
create or replace function public.pss_admin_salvar_dados_recebimento(p_dados jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_id uuid;v_lot text:=trim(p_dados->>'loteria');v_tipo text:=coalesce(nullif(trim(p_dados->>'tipoRecebimento'),''),'PIX');begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;if v_lot='' or trim(coalesce(p_dados->>'nomeCompleto',''))='' then raise exception 'DADOS_RECEBIMENTO_INCOMPLETOS';end if;select id into v_id from public.dados_recebimento where lower(loteria)=lower(v_lot) and lower(tipo_recebimento)=lower(v_tipo) limit 1;if v_id is null then insert into public.dados_recebimento(loteria,tipo_recebimento,nome_completo,tipo_pix,chave_pix,banco,agencia,conta,operacao,obs,ativo) values(v_lot,v_tipo,p_dados->>'nomeCompleto',p_dados->>'tipoPix',p_dados->>'chavePix',p_dados->>'banco',p_dados->>'agencia',p_dados->>'conta',p_dados->>'operacao',p_dados->>'obs',lower(coalesce(p_dados->>'ativo','sim')) in('true','sim','1')) returning id into v_id;else update public.dados_recebimento set nome_completo=p_dados->>'nomeCompleto',tipo_pix=p_dados->>'tipoPix',chave_pix=p_dados->>'chavePix',banco=p_dados->>'banco',agencia=p_dados->>'agencia',conta=p_dados->>'conta',operacao=p_dados->>'operacao',obs=p_dados->>'obs',ativo=lower(coalesce(p_dados->>'ativo','sim')) in('true','sim','1'),updated_at=now() where id=v_id;end if;return jsonb_build_object('ok',true,'sucesso',true,'id',v_id);end$$;
create or replace function public.pss_admin_registrar_jogo_realizado(p_dados jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_admin uuid:=public.pss_usuario_id_atual();v_sub text:=public.pss_claim_sub();v_path text:=trim(coalesce(p_dados->>'storagePath',''));v_id uuid;begin if not public.pss_is_admin() then raise exception 'ACESSO_ADMIN_NEGADO';end if;if v_path='' or position(v_sub||'/' in v_path)<>1 then raise exception 'CAMINHO_STORAGE_INVALIDO';end if;if lower(coalesce(p_dados->>'mimeType','')) not in('image/jpeg','image/png','image/webp','application/pdf') then raise exception 'FORMATO_ARQUIVO_NAO_PERMITIDO';end if;insert into public.jogos_realizados(bolao_id,loteria,concurso,data_jogo,mes_referencia,obs,nome_arquivo,mime_type,storage_bucket,storage_path,tamanho_bytes,hash_arquivo,status,enviado_por) values(nullif(p_dados->>'bolaoId',''),coalesce(p_dados->>'loteria',''),p_dados->>'concurso',nullif(p_dados->>'dataJogo','')::date,p_dados->>'mesReferencia',p_dados->>'obs',p_dados->>'nomeArquivo',p_dados->>'mimeType','jogos-realizados',v_path,nullif(p_dados->>'tamanhoBytes','')::bigint,nullif(p_dados->>'hash',''),'ATIVO',v_admin) returning id into v_id;return jsonb_build_object('ok',true,'sucesso',true,'id',v_id);end$$;

